-- Migration 0026: menyambungkan hasil deteksi AI, data obat, dan stok ke rotasi.
--   * hama.ambang_*                  ambang tingkat serangan dari jumlah per foto (sama dengan
--                                    PestKind di aplikasi; diuji di test/rotation-ai-link.test.js)
--   * rekomendasi_perawatan.tingkat_model  tingkat menurut foto, disimpan terpisah dari pilihan petani
--   * merek_obat, merek_bahan         merek insektisida terdaftar dan bahan aktifnya, untuk mengenali
--                                    barang stok bernama merek saat rekomendasi diterima

ALTER TABLE hama ADD COLUMN ambang_sedang INTEGER CHECK (ambang_sedang IS NULL OR ambang_sedang > 0);
ALTER TABLE hama ADD COLUMN ambang_berat INTEGER CHECK (ambang_berat IS NULL OR ambang_berat > 0);
UPDATE hama SET ambang_sedang = 3, ambang_berat = 8 WHERE kode_hama = 'thrips';
UPDATE hama SET ambang_sedang = 2, ambang_berat = 5 WHERE kode_hama = 'whitefly';
UPDATE hama SET ambang_sedang = 2, ambang_berat = 3 WHERE kode_hama = 'aphids';

-- Model v4.2 hanya punya dua kelas (ml/artifacts/labels.txt: 0 whitefly, 1 aphids). Thrips tetap
-- ada untuk riwayat lama dan saran manual, di luar indeks model. Nilai sementara menghindari UNIQUE.
UPDATE hama SET indeks_model = indeks_model + 100;
UPDATE hama SET indeks_model = 0 WHERE kode_hama = 'whitefly';
UPDATE hama SET indeks_model = 1 WHERE kode_hama = 'aphids';
UPDATE hama SET indeks_model = 2 WHERE kode_hama = 'thrips';

ALTER TABLE rekomendasi_perawatan ADD COLUMN tingkat_model TEXT
  CHECK (tingkat_model IS NULL OR tingkat_model IN ('ringan', 'sedang', 'berat'));

CREATE TABLE merek_obat (
  id_merek INTEGER PRIMARY KEY,
  nama_merek TEXT NOT NULL CHECK (length(nama_merek) BETWEEN 1 AND 200),
  -- Nama dinormalkan (huruf besar, tanda baca disederhanakan) dan tanpa konsentrasi/formulasi.
  kunci TEXT NOT NULL CHECK (length(kunci) BETWEEN 1 AND 200),
  kunci_dasar TEXT NOT NULL CHECK (length(kunci_dasar) BETWEEN 1 AND 200),
  nomor_pendaftaran TEXT NOT NULL CHECK (length(nomor_pendaftaran) <= 40),
  tanggal_berakhir TEXT NOT NULL
);
CREATE INDEX idx_merek_obat_kunci ON merek_obat (kunci);
CREATE INDEX idx_merek_obat_kunci_dasar ON merek_obat (kunci_dasar);

CREATE TABLE merek_bahan (
  id_merek INTEGER NOT NULL REFERENCES merek_obat (id_merek) ON DELETE CASCADE,
  nama_bahan TEXT NOT NULL CHECK (length(nama_bahan) BETWEEN 1 AND 200),
  -- Null: bahan di luar katalog aplikasi (tetap berarti cara kerja lain).
  id_katalog INTEGER REFERENCES obat_katalog (id_katalog),
  PRIMARY KEY (id_merek, nama_bahan)
);

-- Dibuat oleh docs/data/registri/susun_merek.py dari database pestisida terdaftar Kementan
-- (diambil 2026-11-28). Jangan disunting tangan: ubah skrip lalu buat migrasi baru.
-- 2769 merek insektisida/akarisida, 3427 baris bahan aktif.
